<article class="product-card"><a class="product-image" href="<?= e(url('product.php?id=' . (int)$p['id'])) ?>"><img src="<?= e(product_image($p['image'])) ?>" alt="<?= e($p['name']) ?>"><span class="quick-view">View piece ↗</span></a><div class="product-meta"><span><?= e($p['category_name'] ?? '') ?></span><?php if ((int)$p['stock'] < 1): ?><span class="sold-out">Sold out</span><?php endif; ?></div><h3><a href="<?= e(url('product.php?id=' . (int)$p['id'])) ?>"><?= e($p['name']) ?></a></h3><strong><?= money($p['price']) ?></strong></article>
